package java.util;
public class LinkedList<E> extends AbstractSequentialList<E> implements List<E>,Deque<E>,Cloneable,java.io.Serializable {
    private static class Node<E>{E value;Node<E> prev,next;Node(E v){value=v;}}
    private Node<E> first,last;private int count;
    public LinkedList(){}public LinkedList(Collection<? extends E> c){addAll(c);}
    public int size(){return count;}
    private void linkBefore(E e,Node<E> next){Node<E> n=new Node<E>(e),p=next==null?last:next.prev;n.prev=p;n.next=next;if(p==null)first=n;else p.next=n;if(next==null)last=n;else next.prev=n;count++;modCount++;}
    private E unlink(Node<E> n){if(n.prev==null)first=n.next;else n.prev.next=n.next;if(n.next==null)last=n.prev;else n.next.prev=n.prev;count--;modCount++;return n.value;}
    public void addFirst(E e){linkBefore(e,first);}public void addLast(E e){linkBefore(e,null);}public boolean add(E e){addLast(e);return true;}public boolean offer(E e){return offerLast(e);}public boolean offerFirst(E e){addFirst(e);return true;}public boolean offerLast(E e){addLast(e);return true;}
    public E removeFirst(){if(first==null)throw new NoSuchElementException();return unlink(first);}public E removeLast(){if(last==null)throw new NoSuchElementException();return unlink(last);}public E pollFirst(){return first==null?null:unlink(first);}public E pollLast(){return last==null?null:unlink(last);}public E getFirst(){if(first==null)throw new NoSuchElementException();return first.value;}public E getLast(){if(last==null)throw new NoSuchElementException();return last.value;}public E peekFirst(){return first==null?null:first.value;}public E peekLast(){return last==null?null:last.value;}public E remove(){return removeFirst();}public E poll(){return pollFirst();}public E element(){return getFirst();}public E peek(){return peekFirst();}public void push(E e){addFirst(e);}public E pop(){return removeFirst();}public boolean removeFirstOccurrence(Object o){return remove(o);}public boolean removeLastOccurrence(Object o){ListIterator<E> i=listIterator(count);while(i.hasPrevious())if(Objects.equals(o,i.previous())){i.remove();return true;}return false;}
    public ListIterator<E> listIterator(final int index){if(index<0||index>count)throw new IndexOutOfBoundsException();return new ListIterator<E>(){int pos=index,expected=modCount;Node<E> next=node(index),seen;Node<E> node(int i){Node<E> n=first;while(i-->0)n=n.next;return n;}void check(){if(expected!=modCount)throw new ConcurrentModificationException();}public boolean hasNext(){return pos<count;}public boolean hasPrevious(){return pos>0;}public int nextIndex(){return pos;}public int previousIndex(){return pos-1;}public E next(){check();if(!hasNext())throw new NoSuchElementException();seen=next;next=next.next;pos++;return seen.value;}public E previous(){check();if(!hasPrevious())throw new NoSuchElementException();next=next==null?last:next.prev;seen=next;pos--;return seen.value;}public void remove(){check();if(seen==null)throw new IllegalStateException();Node<E> after=seen.next;if(next==seen)next=after;else pos--;unlink(seen);seen=null;expected=modCount;}public void set(E e){check();if(seen==null)throw new IllegalStateException();seen.value=e;}public void add(E e){check();linkBefore(e,next);pos++;seen=null;expected=modCount;}};}
    public Iterator<E> descendingIterator(){final ListIterator<E> i=listIterator(size());return new Iterator<E>(){public boolean hasNext(){return i.hasPrevious();}public E next(){return i.previous();}public void remove(){i.remove();}};}
}
